/**
 * THIS WAS GENERATED BY CLAUDE AS SOMETHING FOR ME TO TEST WITH WHILE
 * LEARNING TO DEVELOP A CYPRESS TEST SUITE
 * 
 * Drop-in replacement for AnkiConnect, for testing app.js without a real
 * Anki instance running.
 *
 * Listens on the same port AnkiConnect normally uses (8765 by default), and
 * implements the subset of the AnkiConnect JSON-RPC protocol that app.js
 * actually calls: deckNames, guiDeckReview, guiCurrentCard, guiShowAnswer,
 * guiAnswerCard.
 *
 * Deck/card data comes from cypress/fixtures/decks.json on startup. Tests
 * can reshape that data or inject failures at runtime through a small
 * control API (see the __control handlers below) instead of editing the
 * fixture file and restarting the server.
 *
 * Usage:
 *   node mock-ankiconnect.js            # listens on :8765
 *   MOCK_PORT=9765 node mock-ankiconnect.js
 */

const http = require("http");
const fs = require("fs");
const path = require("path");

const PORT = process.env.MOCK_PORT || 8765;
const FIXTURE_PATH = path.join(__dirname, "cypress", "fixtures", "decks.json");

function loadFixtureDecks() {
  return JSON.parse(fs.readFileSync(FIXTURE_PATH, "utf8"));
}

// Session state for the deck currently being reviewed.
const state = {
  decks: loadFixtureDecks(),
  currentDeck: null,
  currentIndex: 0,
  scenario: { failHttp: null, delayMs: 0 },
};

function resetState() {
  state.decks = loadFixtureDecks();
  state.currentDeck = null;
  state.currentIndex = 0;
  state.scenario = { failHttp: null, delayMs: 0 };
}

function currentCard() {
  const cards = state.decks[state.currentDeck];
  if (!cards || state.currentIndex >= cards.length) return null;
  return cards[state.currentIndex];
}

// Mirrors AnkiConnect's actual JSON-RPC actions, only for what app.js uses.
function handleAction(action, params) {
  switch (action) {
    case "deckNames":
      return { result: Object.keys(state.decks), error: null };

    case "guiDeckReview":
      state.currentDeck = params && params.name;
      state.currentIndex = 0;
      return { result: true, error: null };

    case "guiCurrentCard": {
      const card = currentCard();
      // Real AnkiConnect returns `false` when nothing is being reviewed
      // (e.g. an empty deck, or no guiDeckReview call yet).
      if (!card) return { result: false, error: null };
      return {
        result: {
          question: card.question,
          answer: card.answer,
          deckName: state.currentDeck,
        },
        error: null,
      };
    }

    case "guiShowAnswer":
      return { result: true, error: null };

    case "guiAnswerCard":
      state.currentIndex += 1;
      return { result: true, error: null };

    default:
      return { result: null, error: `mock-ankiconnect: unimplemented action "${action}"` };
  }
}

function readBody(request) {
  return new Promise((resolve, reject) => {
    let body = "";
    request.on("data", (chunk) => (body += chunk));
    request.on("end", () => resolve(body));
    request.on("error", reject);
  });
}

function sendJSON(response, statusCode, payload) {
  const body = JSON.stringify(payload);
  response.writeHead(statusCode, { "Content-Type": "application/json" });
  response.end(body);
}

const server = http.createServer(async (request, response) => {
  const body = await readBody(request);

  // --- Control API: lets Cypress tests shape mock behavior at runtime. ---
  if (request.url === "/__control/reset" && request.method === "POST") {
    resetState();
    return sendJSON(response, 200, { ok: true });
  }

  if (request.url === "/__control/decks" && request.method === "POST") {
    state.decks = JSON.parse(body);
    state.currentDeck = null;
    state.currentIndex = 0;
    return sendJSON(response, 200, { ok: true });
  }

  if (request.url === "/__control/scenario" && request.method === "POST") {
    const scenario = JSON.parse(body || "{}");
    state.scenario.failHttp = scenario.failHttp || null;
    state.scenario.delayMs = scenario.delayMs || 0;
    return sendJSON(response, 200, { ok: true });
  }

  // --- AnkiConnect protocol ---
  if (state.scenario.delayMs > 0) {
    await new Promise((r) => setTimeout(r, state.scenario.delayMs));
  }

  if (state.scenario.failHttp) {
    response.writeHead(state.scenario.failHttp, { "Content-Type": "text/plain" });
    response.end("mock-ankiconnect: simulated failure");
    return;
  }

  let request_json;
  try {
    request_json = JSON.parse(body);
  } catch (e) {
    return sendJSON(response, 400, { result: null, error: "invalid JSON request" });
  }

  const result = handleAction(request_json.action, request_json.params);
  sendJSON(response, 200, result);
});

server.listen(PORT, () => {
  console.log(`mock-ankiconnect listening on :${PORT}`);
});
